tools.example:
# Tcl equivalents for what the Netlist window shows
get_cells -hierarchical -filter {IS_PRIMITIVE && PARENT == u_core}
get_nets -of_objects [get_cells u_core] 
get_cells -hierarchical -filter {IS_BLACKBOX}

# Same information from Tcl
foreach pin [get_package_pins -of_objects [get_iobanks 34]] {
  puts "$pin [get_property PIN_FUNC $pin] [get_property MAX_DELAY $pin]"
}

# Tcl equivalents recorded by the GUI
set_msg_config -id {Synth 8-3331} -suppress
set_msg_config -id {Place 30-12} -new_severity {CRITICAL WARNING}
set_msg_config -id {Common 17-349} -limit 10
get_msg_config -count -severity {CRITICAL WARNING}
